<script lang="ts">
 import {tick} from 'svelte';
 import type {GoalColumn,GoalFilters} from '../../lib/goals/filters';
 import {emptyFilters,filterActive} from '../../lib/goals/filters';
 let {column,label,filters,projects,onApply}:{column:GoalColumn;label:string;filters:GoalFilters;projects:{id:string;name:string}[];onApply:(filters:GoalFilters)=>void}=$props();
 let dialog:HTMLDialogElement,button:HTMLButtonElement,open=$state(false),draft=$state<GoalFilters>(emptyFilters()),error=$state('');
 function close(){dialog.close();open=false;button.focus();}
 async function show(){draft=structuredClone($state.snapshot(filters));error='';dialog.show();open=true;await tick();const r=button.getBoundingClientRect();dialog.style.left=`${Math.max(12,Math.min(innerWidth-dialog.offsetWidth-12,r.left))}px`;dialog.style.top=`${Math.max(12,r.bottom+dialog.offsetHeight+10<innerHeight?r.bottom+6:r.top-dialog.offsetHeight-6)}px`;dialog.querySelector<HTMLElement>('input,select')?.focus();}
 function apply(){if(column==='due'&&draft.due.from&&draft.due.to&&draft.due.from>draft.due.to){error='Choose an end date on or after the start date.';return;}onApply(draft);close();}
 function clear(){const next={...filters,[column]:emptyFilters()[column],...(column==='state'?{completion:'all'}:{})};onApply(next);close();}
 function key(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();close();}if(event.key==='Tab'){const controls=[...dialog.querySelectorAll<HTMLElement>('button,input:not(:disabled),select')];const first=controls[0],last=controls.at(-1);if(event.shiftKey&&event.target===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&event.target===last){event.preventDefault();first.focus();}}}
</script>
<svelte:window onclick={event=>{if(open&&!dialog.contains(event.target as Node)&&!button.contains(event.target as Node))close();}} onresize={()=>{if(open)close();}}/>
<button bind:this={button} class:filtered={filterActive(column,filters)} class="trigger" aria-label={`${label} filter`} aria-haspopup="dialog" aria-expanded={open} onclick={()=>open?close():show()}><span>{label}</span><svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true">{#if filterActive(column,filters)}<circle cx="6" cy="6" r="2" fill="currentColor"/>{:else}<path d="m3 4.5 3 3 3-3" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round"/>{/if}</svg></button>
<dialog bind:this={dialog} aria-label={`${label} filter`} onkeydown={key} oncancel={()=>open=false}>
 <form onsubmit={event=>{event.preventDefault();apply();}}><header><span>{label}</span><button type="button" aria-label={`Close ${label.toLowerCase()} filter`} onclick={close}>×</button></header>
 {#if column==='goal'}<label>Contains<input type="search" placeholder="Goal name" bind:value={draft.goal}/></label>
 {:else if column==='project'}<label>Project<select bind:value={draft.project}><option value="all">All projects</option>{#each projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label>
 {:else if column==='state'}<label>State<select bind:value={draft.state}><option value="all">All states</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label><label>Completion<select bind:value={draft.completion}><option value="all">All completion</option><option value="done">Done</option><option value="open">Not done</option></select></label>
 {:else if column==='due'}<label>On or after<input type="date" bind:value={draft.due.from}/></label><label>On or before<input type="date" bind:value={draft.due.to}/></label>
 {:else}<label>Condition<select bind:value={draft[column].op}><option value="any">Any value</option><option value="gte">At least (≥)</option><option value="lte">At most (≤)</option><option value="eq">Equals (=)</option>{#if column==='current'}<option value="missing">No reading</option><option value="present">Has a reading</option>{/if}</select></label>{#if ['gte','lte','eq'].includes(draft[column].op)}<label>Value<input type="number" step="any" required value={draft[column].value} oninput={e=>{draft[column].value=e.currentTarget.value}}/></label>{/if}{/if}
 {#if error}<p role="alert">{error}</p>{/if}<footer><button type="button" onclick={clear}>Clear</button><button type="submit">Apply</button></footer></form>
</dialog>
<style>
.trigger{display:flex;align-items:center;gap:7px;width:100%;min-height:34px;padding:7px 5px;border:0;border-radius:4px;background:none;color:var(--text-faintest);font:400 12px/1.35 var(--font-ui);white-space:nowrap;text-align:left;cursor:pointer}.trigger.filtered{color:var(--accent-bright)}.trigger:hover,.trigger[aria-expanded=true]{background:var(--surface-2);color:var(--text-muted)}dialog{position:fixed;z-index:80;margin:0;width:260px;max-width:calc(100vw - 24px);padding:14px;border:1px solid var(--border-color);border-radius:8px;background:var(--surface-2);box-shadow:var(--shadow-float);color:var(--text-default);font:400 13px/1.45 var(--font-ui);text-align:left}header{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;font-weight:500;color:var(--text-muted)}header button{font-size:18px}button{border:0;background:none;color:var(--text-muted);cursor:pointer;font:inherit}label{display:flex;flex-direction:column;gap:7px;font-size:12px;color:var(--text-faintest);margin-top:12px}input,select{display:block;width:100%;min-width:0;height:36px;padding:7px 9px;border:1px solid var(--border-color);border-radius:5px;background:var(--surface-recessed);color:var(--text-default);font:400 13px/1.4 var(--font-ui);color-scheme:dark}footer{display:flex;justify-content:space-between;gap:10px;margin-top:16px;padding-top:12px;border-top:1px solid var(--border-color)}footer button{padding:6px 10px;border-radius:5px}footer button[type=submit]{background:var(--surface-1);color:var(--text-default)}p{color:var(--accent-error);font-size:12px}
</style>
